    tavily: async (q, n) => (((await curlJson('https://api.tavily.com/search', { Authorization: 'Bearer ' + crmKey('tavily') }, { query: q, max_results: n, search_depth: 'basic' })).results) || []).map((r) => [r.title, r.url, r.content || '']),
